import type { AssetEntry } from "@/domain/engine/types";
import { PRODUCTS } from "./products";

/**
 * The asset manifest: the only place visuals are declared. Everything else refers to an `AssetId`.
 * Door visuals are generated by the schematic renderer. Gallery photos are CC0 images from Wikimedia Commons
 * (credits in public/gallery/CREDITS.md).
 */
const CC0 = "CC0 1.0 (Wikimedia Commons); see public/gallery/CREDITS.md.";

const productAssets: AssetEntry[] = PRODUCTS.map((p) => ({
  id: p.assetId,
  kind: "schematic",
  alt: `${p.name} door (schematic)`,
  license: "Generated by the app's schematic renderer from the product's defaults.",
}));

const galleryAssets: AssetEntry[] = [
  { id: "gallery.house-1", kind: "image", src: "/gallery/house-1.jpg", alt: "White clapboard house with a covered front door", license: CC0 },
  { id: "gallery.house-2", kind: "image", src: "/gallery/house-2.jpg", alt: "Red brick house with a panelled front door", license: CC0 },
  { id: "gallery.house-3", kind: "image", src: "/gallery/house-3.jpg", alt: "Yellow stucco house with a columned entrance", license: CC0 },
  { id: "gallery.house-4", kind: "image", src: "/gallery/house-4.jpg", alt: "Modern stucco duplex with timber front doors", license: CC0 },
  { id: "gallery.house-5", kind: "image", src: "/gallery/house-5.jpg", alt: "White single-storey house with a red front door", license: CC0 },
  { id: "gallery.room-1", kind: "image", src: "/gallery/room-1.jpg", alt: "Modern living room with a brick wall", license: CC0 },
];

export const ASSETS: Readonly<Record<string, AssetEntry>> = Object.fromEntries(
  [...productAssets, ...galleryAssets].map((a) => [a.id, a]),
);

export function getAsset(id: string): AssetEntry {
  const a = ASSETS[id];
  if (!a) throw new Error(`Unknown asset "${id}". Add it to the asset manifest first.`);
  return a;
}
